# Valid digits: 0, 1, 6, 8, 9
# Their rotations: 0→0, 1→1, 6→9, 8→8, 9→6

def confusingNumberII(N: int) -> int:
    # Mapping for rotation (as dict for O(1) lookups)
    rotate = {0:0, 1:1, 6:9, 8:8, 9:6}
    valid_digits = [0,1,6,8,9]

    result = 0

    def is_confusing(num):
        rot, original = 0, num
        while num > 0:
            d = num % 10
            rot = rot * 10 + rotate[d]
            num //= 10
        return rot != original

    def dfs(curr):
        nonlocal result
        if curr > N:
            return
        if curr != 0 and is_confusing(curr):
            result += 1
        for d in valid_digits:
            # Skip numbers with leading zeros
            if curr == 0 and d == 0:
                continue
            nxt = curr * 10 + d
            if nxt > N:
                break
            dfs(nxt)

    dfs(0)
    return result
